import flask
from flask import request, jsonify, g
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def audit_log(action, detail):
    """Write to audit table - best effort"""
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO audit_log (action, detail, ts) VALUES (%s, %s, NOW())",
            (action, detail)
        )
        conn.commit()
    except Exception:
        pass

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria.
    Supports: name, email, department, role
    Results are filtered by caller's tenant scope.
    """
    tenant_id = request.headers.get('X-Tenant-ID', '1')
    search_field = request.args.get('field', 'name')
    search_value = request.args.get('q', '')

    # Validate field against allowed columns
    allowed_fields = ['name', 'email', 'department', 'role', 'employee_id']
    if search_field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with tenant isolation
    # Note: search_field is validated above, search_value is user input
    query = f"SELECT id, name, email, department, role FROM users WHERE tenant_id = '{tenant_id}' AND {search_field} ILIKE '%{search_value}%' ORDER BY name LIMIT 50"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()

        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'name': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })

        audit_log('user_search', f'field={search_field} q={search_value[:50]} tenant={tenant_id}')
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    tenant_id = request.headers.get('X-Tenant-ID', '1')
    conn = get_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT id, name, email, department, role, phone, hire_date FROM users WHERE id = %s AND tenant_id = %s",
        (user_id, tenant_id)
    )
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({
        'id': row[0], 'name': row[1], 'email': row[2],
        'department': row[3], 'role': row[4],
        'phone': row[5], 'hire_date': str(row[6])
    })

@app.route('/api/reports/headcount', methods=['GET'])
def headcount_report():
    tenant_id = request.headers.get('X-Tenant-ID', '1')
    dept = request.args.get('dept', '')

    conn = get_db()
    cur = conn.cursor()
    # This one uses parameterized query correctly
    if dept:
        cur.execute(
            "SELECT department, COUNT(*) FROM users WHERE tenant_id = %s AND department = %s GROUP BY department",
            (tenant_id, dept)
        )
    else:
        cur.execute(
            "SELECT department, COUNT(*) FROM users WHERE tenant_id = %s GROUP BY department ORDER BY department",
            (tenant_id,)
        )
    rows = cur.fetchall()
    return jsonify({'headcount': [{'dept': r[0], 'count': r[1]} for r in rows]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
